    },
    {
      "headline": "President Rinkēvičs speaks at 40th anniversary Chornobyl commemoration",
      "summary": "President Edgars Rinkēvičs attended and addressed a Chornobyl disaster commemoration at Stradiņš Hospital on April 24–26, noting that the accident—which mobilised over 6,000 Latvians in clean-up operations—helped collapse the Soviet information empire. He called on the government and Saeima to address outstanding issues for Latvian Chornobyl liquidators."
    },
    {
      "headline": "Domestic violence law standoff: Siliņa denies ordering Istanbul Convention alternative; Welfare Ministry confirms no mandate received",
      "summary": "The Welfare Ministry (led by ZZS) told a Saeima committee that it had received no instruction from PM Siliņa to draft a domestic violence prevention law intended as an alternative to the Istanbul Convention, which Latvia's parliament voted to denounce in 2023 but President Rinkēvičs declined to promulgate. A separate LSM article confirmed the Ministry planned to produce a draft by autumn 2026."
    },
    {
      "headline": "Swedbank branch manager sentenced to six years for defrauding elderly clients over 17 years",
      "summary": "The Zemgale District Court sentenced a Swedbank employee, Larisa Bobrova, to six years in prison on April 22 for unlawfully managing client funds, document forgery, and payment instrument fraud between 2003 and 2020. She was ordered to repay the bank €202,555 and had exploited digitally inactive elderly clients across the Ogre and Bauska branches."
    }
  ]
}

